        if ($request->wantsJson()) {
            return response()->json([
                'success' => false,
                'message' => $errorMessage,
            ], 422);
        }

        return redirect()->route('vehicles.index')->with('error', $errorMessage);
    }

    DB::table('vehicles')->where('id', $id)->delete();

    if ($request->wantsJson()) {
        return response()->json([
            'success' => true,
            'message' => 'Kendaraan berhasil dihapus.',
        ]);
    }

    return redirect()->route('vehicles.index')->with('success', 'Kendaraan berhasil dihapus.');
}

public function index(Request $request)
{
    $validated = $request->validate([
        'search' => 'nullable|string|max:100',
        'status' => 'nullable|string|in:active,maintenance,inactive',
        'per_page' => 'nullable|integer|in:10,25,50',
    ]);

    $query = DB::table('vehicles')
        ->leftJoin('ritases', 'vehicles.id', '=', 'ritases.vehicle_id')
        ->select(
            'vehicles.id',
            'vehicles.license_plate',
            'vehicles.vehicle_type',
            'vehicles.status',
            'vehicles.created_at',
            'vehicles.updated_at',
            DB::raw('COUNT(ritases.id) as ritase_count')
        )
        ->groupBy(
            'vehicles.id',
            'vehicles.license_plate',
            'vehicles.vehicle_type',
            'vehicles.status',
            'vehicles.created_at',
            'vehicles.updated_at'
        )
        ->orderBy('vehicles.license_plate');

    if (!empty($validated['search'])) {
        $searchTerm = '%' . strtolower(trim($validated['search'])) . '%';
        $query->whereRaw('LOWER(vehicles.license_plate) LIKE ?', [$searchTerm]);
    }

    if (!empty($validated['status'])) {
        $query->where('vehicles.status', $validated['status']);
    }

    $search = trim((string) ($validated['search'] ?? ''));
    $perPage = (int) ($validated['per_page'] ?? 10);
    $vehicles = $query->paginate($perPage)->withQueryString();
    $summary = [
        'total' => DB::table('vehicles')->count(),
        'active' => DB::table('vehicles')->where('status', 'active')->count(),
        'maintenance' => DB::table('vehicles')->where('status', 'maintenance')->count(),
        'inactive' => DB::table('vehicles')->where('status', 'inactive')->count(),
    ];

    if ($request->wantsJson()) {
        return response()->json($vehicles);
    }

    return view('vehicles.index', compact('vehicles', 'validated', 'search', 'perPage', 'summary'));
}

public function store(Request $request)
{
    $rawPlate = $request->input('license_plate');
    if (is_string($rawPlate)) {
        $request->merge(['license_plate' => strtoupper(trim($rawPlate))]);
    }

    $validated = $request->validate([
        'license_plate' => 'required|string|max:20|unique:vehicles,license_plate',
        'vehicle_type' => 'required|string|in:truck,pickup,lainnya',
        'status' => 'nullable|string|in:active,maintenance,inactive',
    ]);

    $id = DB::table('vehicles')->insertGetId([
        'license_plate' => strtoupper(trim($validated['license_plate'])),
        'vehicle_type' => $validated['vehicle_type'],
        'status' => $validated['status'] ?? 'active',
        'created_at' => now(),
        'updated_at' => now(),
    ]);

    if ($request->wantsJson()) {
        return response()->json(['success' => true, 'id' => $id], 201);
    }

    return redirect()->route('vehicles.index')->with('success', 'Kendaraan operasional berhasil didaftarkan.');
}

public function update(Request $request, $id)
{
    $vehicle = DB::table('vehicles')->where('id', $id)->first();
    if (! $vehicle) {
        abort(404);
    }

    $rawPlate = $request->input('license_plate');
    if (is_string($rawPlate)) {
        $request->merge(['license_plate' => strtoupper(trim($rawPlate))]);
    }

    $validated = $request->validate([
        'license_plate' => 'required|string|max:20|unique:vehicles,license_plate,' . $id,
        'vehicle_type' => 'required|string|in:truck,pickup,lainnya',
        'status' => 'required|string|in:active,maintenance,inactive',
    ]);

    DB::table('vehicles')->where('id', $id)->update([
        'license_plate' => strtoupper(trim($validated['license_plate'])),
        'vehicle_type' => $validated['vehicle_type'],
        'status' => $validated['status'],
        'updated_at' => now(),
    ]);

    $updatedVehicle = DB::table('vehicles')->where('id', $id)->first();

    if ($request->wantsJson()) {
        return response()->json([
            'success' => true,
            'message' => 'Data kendaraan berhasil diperbarui.',
            'data' => $updatedVehicle,
        ]);
    }

    return redirect()->route('vehicles.index')->with('success', 'Data kendaraan berhasil diperbarui.');
}

App\\Http\\Middleware\\EnsureActiveAccou.code:
public function handle(Request $request, Closure $next)
{
    if (Auth::check()) {
        // Read storage, not a potentially stale guard instance.
        $user = User::find(Auth::id());
        $stamp = $request->session()->get('v2_auth_stamp');
        $current = $user ? [(int) $user->id, (int) $user->auth_version] : null;
        $missingAllowed = $user && ((int) $user->auth_version === 1 || Auth::viaRemember());
        if (!$user || !$user->is_active || ($stamp !== null && $stamp !== $current) || ($stamp === null && !$missingAllowed)) {
            Auth::logout();
            $request->session()->invalidate();
            $request->session()->regenerateToken();
            if ($request->expectsJson()) return response()->json(['message'=>'Sesi berakhir. Silakan login kembali.'], 401);
            return redirect()->route('login')->withErrors(['email'=>'Sesi berakhir. Silakan login kembali.']);
        }
        Auth::setUser($user);
        $request->session()->put('v2_auth_stamp', $current);
    }
    return $next($request);
}

App\\Http\\Middleware\\V2Cutover::handle.code:
public function handle(Request $request, Closure $next)
{
    if (config('v2.enabled') && $request->is('demo-setup', 'demo-setup/*')) {
        abort(404);
    }
    if (! config('v2.enabled') || $request->is('v2', 'v2/*', 'login', 'logout', 'up')) {
        return $next($request);
    }
    if (! Auth::check()) {
        return $next($request);
    }
    $role = app(Operations::class)->role(Auth::id());
    if ($request->path() === '/') {
        return $next($request);
    }
    // Legacy remains an admin read-only archive after cutover.
    abort_unless($role === 'admin' && $request->isMethod('GET'), 403, 'Gunakan alur V2; arsip lama hanya dapat dibaca admin.');

    return $next($request);
}

App\\Services\\AccountAdjustmentService:.code:
public function post(array $data, int $userId): int
{
    return DB::transaction(function () use ($data, $userId): int {
        $opening = DB::table('opening_balances')->where('singleton_key', 1)->lockForUpdate()->first();
        $accounts = DB::table('chart_of_accounts')
            ->whereIn('account_code', [$data['account_code'], $data['counter_account_code']])
            ->orderBy('account_code')->lockForUpdate()->get()->keyBy('account_code');
        if ($accounts->count() !== 2 || $accounts->contains(fn ($account) => ! $account->is_active)) {
            throw new InvalidArgumentException('Pilih dua akun aktif yang berbeda.');
        }
        $account = $accounts[$data['account_code']];
        $target = BigDecimal::of($data['target_balance'])->toScale(2);
        $signedTarget = $account->normal_balance === 'credit' ? $target->negated() : $target;
        $difference = $signedTarget->minus($this->balances->balance($account->account_code));
        if ($difference->isZero()) {
            throw new InvalidArgumentException('Saldo sudah sesuai; tidak ada penyesuaian yang perlu diposting.');
        }
        if ($difference->abs()->isGreaterThan('99999999999999999.99')) {
            throw new InvalidArgumentException('Selisih penyesuaian melebihi batas penyimpanan.');
        }
        $counter = $accounts[$data['counter_account_code']];
        foreach ([$account->account_code => $signedTarget, $counter->account_code => $this->balances->balance($counter->account_code)->minus($difference)] as $code => $result) {
            if (in_array((string) $code, ['1101', '1102'], true) && $result->isNegative()) {
                throw new InvalidArgumentException('Penyesuaian tidak boleh membuat saldo Kas atau Bank negatif.');
            }
        }
        $id = DB::table('journal_entries')->insertGetId([
            'reference_type' => 'adjustment', 'reference_id' => null,
            'description' => 'Penyesuaian saldo oleh pengguna #'.$userId.': '.$data['description'],
            'transaction_date' => $data['transaction_date'], 'created_at' => now(), 'updated_at' => now(),
        ]);
        foreach ([$account, $counter] as $index => $lineAccount) {
            $debit = ($index === 0) === $difference->isPositive();
            DB::table('journal_entry_lines')->insert([
                'journal_entry_id' => $id, 'account_code' => $lineAccount->account_code,
                'account_name' => $lineAccount->account_name,
                'debit' => $debit ? (string) $difference->abs() : '0.00',
                'credit' => $debit ? '0.00' : (string) $difference->abs(),
                'created_at' => now(), 'updated_at' => now(),
            ]);
        }
        if (! $opening || $opening->status === 'draft') {
            $values = [
                'transaction_date' => $data['transaction_date'],
                'cash_amount' => (string) $this->balances->balance('1101'),
                'bank_amount' => (string) $this->balances->balance('1102'),
                'status' => 'posted', 'journal_entry_id' => $id, 'posted_at' => now(), 'updated_at' => now(),
            ];
            if ($opening) {
                DB::table('opening_balances')->where('id', $opening->id)->update($values);
            } else {
                DB::table('opening_balances')->insert($values + ['singleton_key' => 1, 'created_at' => now()]);
            }
        }

        return $id;
    });
}

