private function quantity(BigDecimal $value): string
{
    $text = (string) $value->toScale(4, RoundingMode::HalfUp);
    [$int, $frac] = explode('.', $text);
    $frac = rtrim($frac, '0');

    return preg_replace('/\B(?=(\d{3})+(?!\d))/', '.', $int).($frac !== '' ? ','.$frac : '');
}

App\\Services\\V2\\AdminSummary::stockWa.code:
private function stockWatch(): array
{
    $rows = DB::table('products')->where('is_active', true)
        ->where(fn ($q) => $q->where('stock_quantity', '<=', 0)->orWhereColumn('stock_quantity', '<=', 'min_stock'))
        ->get(['name', 'unit', 'stock_quantity', 'min_stock']);

    $items = [];
    foreach ($rows as $row) {
        $qty = BigDecimal::of((string) $row->stock_quantity);
        $min = BigDecimal::of((string) ($row->min_stock ?? '0'));
        $items[] = ['row' => $row, 'qty' => $qty, 'min' => $min, 'out' => $qty->isLessThanOrEqualTo(0)];
    }
    usort($items, function (array $a, array $b): int {
        if ($a['out'] !== $b['out']) {
            return $a['out'] ? -1 : 1;
        }
        // Rasio stok terhadap minimum, terkecil lebih dulu; perbandingan silang agar tetap BigDecimal.
        $left = $a['qty']->multipliedBy($b['min']->isZero() ? 1 : $b['min']);
        $right = $b['qty']->multipliedBy($a['min']->isZero() ? 1 : $a['min']);

        return $left->compareTo($right) ?: strcmp((string) $a['row']->name, (string) $b['row']->name);
    });

    return array_map(fn (array $item): array => [
        'name' => (string) $item['row']->name,
        'qty' => $this->quantity($item['qty']),
        'unit' => (string) ($item['row']->unit ?? ''),
        'min' => $this->quantity($item['min']),
        'out' => $item['out'],
    ], array_slice($items, 0, self::WATCH_LIMIT));
}

App\\Services\\V2\\CustomerLookup::nextC.code:
private function nextCode(): string
{
    $last = DB::table('v2_parties')
        ->where('kind', 'customer')
        ->where('code', 'like', 'CUS-%')
        ->orderByDesc('code')
        ->value('code');

    $next = $last ? ((int) substr((string) $last, 4)) + 1 : 1;
    do {
        $code = 'CUS-'.str_pad((string) $next, 4, '0', STR_PAD_LEFT);
        $next++;
    } while (DB::table('v2_parties')->where('code', $code)->exists());

    return $code;
}

App\\Services\\V2\\CustomerLookup::resol.code:
public function resolve(int $actor, string $name): array
{
    $this->operations->requireRole($actor, ['admin', 'cashier']);
    $name = trim(preg_replace('/\s+/u', ' ', $name) ?? '');
    if (mb_strlen($name) < self::MIN_LENGTH) {
        throw new RuntimeException('Nama pelanggan minimal '.self::MIN_LENGTH.' huruf.');
    }
    if (mb_strlen($name) > self::MAX_NAME) {
        throw new RuntimeException('Nama pelanggan maksimal '.self::MAX_NAME.' huruf.');
    }

    return DB::transaction(function () use ($name) {
        $existing = DB::table('v2_parties')
            ->where('kind', 'customer')
            ->whereRaw('LOWER(name) = ?', [mb_strtolower($name)])
            ->lockForUpdate()
            ->first(['id', 'code', 'name', 'is_active', 'price_tier']);

        if ($existing) {
            if (! $existing->is_active) {
                throw new RuntimeException('Pelanggan "'.$existing->name.'" sedang diarsipkan. Minta admin mengaktifkannya.');
            }

            return ['id' => (int) $existing->id, 'code' => (string) $existing->code, 'name' => (string) $existing->name, 'price_tier' => (string) ($existing->price_tier ?: 'retail'), 'created' => false];
        }

        $code = $this->nextCode();
        $id = DB::table('v2_parties')->insertGetId([
            'kind' => 'customer', 'code' => $code, 'name' => $name, 'is_active' => true,
            'created_at' => now(), 'updated_at' => now(),
        ]);

        return ['id' => (int) $id, 'code' => $code, 'name' => $name, 'price_tier' => 'retail', 'created' => true];
    });
}

App\\Services\\V2\\CustomerLookup::searc.code:
public function search(string $term, int $limit = 8): array
{
    $term = trim($term);
    if (mb_strlen($term) < self::MIN_LENGTH) {
        return [];
    }

    return DB::table('v2_parties')
        ->where('kind', 'customer')
        ->where('is_active', true)
        ->where(fn ($query) => $query->where('name', 'like', '%'.$term.'%')->orWhere('code', 'like', $term.'%'))
        ->orderBy('name')
        ->limit(max(1, min($limit, 20)))
        ->get(['id', 'code', 'name', 'price_tier'])
        ->map(fn ($row) => ['id' => (int) $row->id, 'code' => (string) $row->code, 'name' => (string) $row->name, 'price_tier' => (string) ($row->price_tier ?: 'retail')])
        ->all();
}

