private function sumRows(iterable $rows, callable $value): array
{
    $sum = BigDecimal::zero();
    $count = 0;
    foreach ($rows as $row) {
        $sum = $sum->plus($value($row));
        $count++;
    }

    return [(string) $sum->toScale(2), $count];
}

